CREATE DATABASE IF NOT EXISTS smart_attendance CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_attendance;
CREATE TABLE users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','teacher') NOT NULL,active TINYINT(1) DEFAULT 1);
CREATE TABLE teacher_sections(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,teacher_id INT UNSIGNED NOT NULL,department VARCHAR(100) NOT NULL,year VARCHAR(30) NOT NULL,section VARCHAR(20) NOT NULL,UNIQUE KEY uq_ts(teacher_id,department,year,section),FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE students(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,roll_number VARCHAR(60) NOT NULL UNIQUE,student_name VARCHAR(150) NOT NULL,department VARCHAR(100) NOT NULL,year VARCHAR(30) NOT NULL,section VARCHAR(20) NOT NULL,active TINYINT(1) DEFAULT 1,KEY idx_class(department,year,section));
CREATE TABLE attendance_sessions(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,teacher_id INT UNSIGNED NOT NULL,department VARCHAR(100) NOT NULL,year VARCHAR(30) NOT NULL,section VARCHAR(20) NOT NULL,attendance_date DATE NOT NULL,subject VARCHAR(150) NOT NULL,period VARCHAR(50) NOT NULL DEFAULT '',UNIQUE KEY uq_session(teacher_id,department,year,section,attendance_date,subject,period),FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE attendance_records(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id INT UNSIGNED NOT NULL,student_id INT UNSIGNED NOT NULL,status ENUM('Present','Absent') NOT NULL,UNIQUE KEY uq_record(session_id,student_id),FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
